SELECT COUNT(*) FROM TBL_FWGL_LAW_SERVICE
WHERE 1=1

    AND BELONGGROUP = #{belongGroup}

SELECT COUNT(*) FROM TBL_FWGL_REGISTER_MANAGEMENT
WHERE 1=1

    AND BELONGGROUP = #{belongGroup}

SELECT COUNT(*) FROM TBL_FWGL_ACTIVITY_MANAGEMENT
WHERE STATE != 6

    AND BELONGGROUP = #{belongGroup}

SELECT COUNT(*) FROM TBL_FWGL_INSTITUTION_AUDIT
WHERE CREATEDTIME >= #{startDate} AND CREATEDTIME < #{endDate}

    AND BELONGGROUP = #{belongGroup}
